// Survey Drone - detection sweep simulation (Mark 1 demonstration run)
// Run with: node demo.js
'use strict';
var range=[50,8000,2000000], res=[12,0.5,0.02];
console.log("Survey Drone - detection probability vs range");
console.log("==================================================");
for(var m=0;m<3;m++){
  console.log("Mark "+(m+1)+": max range "+range[m]+" km, resolution "+res[m]+" m");
  var row=" ";
  for(var f=1;f<=5;f++){ var d=range[m]*f/5; var p=Math.max(0,100*(1-Math.pow(d/range[m],2))*(res[0]/res[m])); row+="d="+(d/1000).toFixed(0)+"k km:"+(p>99?"~100":p.toFixed(0))+"% "; }
  console.log(row);
}

